import {newestFinanceRecords,visibleFinanceNote} from './finance-import.js';
import {uid,today,validDate} from './model.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rub=n=>(n/100).toLocaleString('ru-RU',{maximumFractionDigits:2})+' ₽';
const schemas={
 cards:[['name','Заказчик','text'],['date','Дата заказа','date'],['incomeMonth','Месяц учёта','month'],['quantity','Кол-во','qty'],['actualQuantity','Факт','qty'],['unitCost','Закупка / шт.','unit'],['unitPrice','Продажа / шт.','unit'],['received','Получено','money'],['note','Комментарий','text']],
 sales:[['name','Товар / источник','text'],['date','Дата','date'],['incomeMonth','Месяц учёта','month'],['quantity','Кол-во','decimal'],['revenue','Цена продажи','money'],['cost','Себестоимость / расходы','money'],['received','Получено','money'],['legacyProfit','Прибыль','signed'],['note','Комментарий','text']],
 stock:[['name','Товар','text'],['quantity','Остаток','qty'],['cost','Закупка / шт.','unit'],['price','Продажа / шт.','money'],['source','Источник','text']],
 accounts:[['name','Банк / счёт','text'],['balance','Остаток','money'],['owned','Принадлежность','owner']],
 creditCards:[['bank','Банк','text'],['debt','Задолженность','money'],['limit','Лимит','money']],
 mortgages:[['name','Ипотека','text'],['initial','Сумма кредита','money']],
 mortgagePayments:[['date','Дата','date'],['amount','Основной долг','money'],['interest','Проценты','money'],['note','Комментарий','text']],
 familyComponents:[['name','Категория','readonly'],['amount','Итог расхода','nullable']],
 familyPayments:[['date','Дата','date'],['category','Категория','familyCategory'],['amount','Расход / возврат','signed'],['note','Комментарий','text']]
};
const moneyTypes=new Set(['money','signed','nullable','unit']);
function number(value,type){const s=String(value).replace(/[\s\u00a0₽]/g,'').replace(',','.');if(s==='')return type==='nullable'?null:0;if(!/^[+-]?\d+(?:\.\d+)?$/.test(s))throw Error('Проверьте число: '+value);const n=Number(s);if(!Number.isFinite(n)||Math.abs(n)>1e12||(!['signed','nullable'].includes(type)&&n<0)||type==='qty'&&!Number.isInteger(n))throw Error('Недопустимое число: '+value);const v=moneyTypes.has(type)?n*100:n;if(type!=='unit'&&moneyTypes.has(type)&&Math.abs(v-Math.round(v))>1e-6)throw Error('Денежная сумма должна быть с точностью до копеек.');return ['unit','decimal'].includes(type)?v:Math.round(v);}
export function createLedgerTables({root,getData,save,render,cardTotals,workDue}){
 let ledgerCardYear=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Novosibirsk',year:'numeric'}).format(new Date());
 let dirty=false,busy=false,moreTab='accounts',loanId='',familyId='';
 const status=()=>`<div class="grid-toolbar"><span class="ledger-status" role="status">Все изменения сохранены</span><div><button data-ledger="cancel">Отменить изменения</button><button class="primary" hidden data-ledger="save">Сохранить изменения</button></div></div><p class="error ledger-error" role="alert"></p>`;
 function rowsFor(key,parent){const d=getData();if(key==='mortgagePayments')return d.mortgages.find(x=>x.id===parent)?.payments||[];if(key==='familyPayments')return d.family.find(x=>x.id===parent)?.payments||[];if(key==='familyComponents')return d.family.find(x=>x.id===parent)?.components||[];if(key==='creditCards')return(d.creditCards||[]).map((x,i)=>({...x,id:x.id||'credit-'+i}));return d[key]||[];}
 function cell(x,field,type,index,key){let value=field==='note'?visibleFinanceNote(x[field]):x[field];if(field==='incomeMonth')value=x.incomeMonth||x.date?.slice(0,7)||'';if(field==='legacyProfit'){value=x.received-x.cost;if(!x.profitOnly)return `<td class="ledger-computed" data-computed="profit">${rub(value)}</td>`;}const locked=type==='readonly'||key==='familyComponents'&&field==='amount'&&!['ЖКХ','Комиссия ЖКХ'].includes(x.name)||key==='sales'&&(x.profitOnly?['revenue','cost','received'].includes(field):field==='legacyProfit');if(locked)return `<td>${key==='sales'&&x.profitOnly&&['revenue','cost','received'].includes(field)||value===null||value===undefined?'—':moneyTypes.has(type)?rub(value):esc(value)}</td>`;if(type==='owner')value=x.owned!==false?'true':'false';const original=value??'';value=moneyTypes.has(type)?value===null||value===undefined?'':value/100:value??'';const common=`${moneyTypes.has(type)?'data-money':''} data-field="${field}" data-cell="${index}" data-original="${esc(value)}" aria-label="${key} ${x.id} ${field}"`;if(type==='owner')return `<td><select ${common}><option value="true" ${x.owned!==false?'selected':''}>Мои средства</option><option value="false" ${x.owned===false?'selected':''}>Чужие средства</option></select></td>`;if(type==='familyCategory')return `<td><select ${common}>${['ЖКХ','Лекарства','Комиссия ЖКХ','Хозяйство','Прочее'].map(c=>`<option ${c===value?'selected':''}>${c}</option>`).join('')}</select></td>`;return `<td><input ${common} value="${esc(value)}" ${type==='date'||type==='month'?`type="${type}"`:moneyTypes.has(type)||['qty','decimal'].includes(type)?'inputmode="decimal"':''}></td>`;}
 function computed(key,x){if(key==='cards'){const t=cardTotals(x);return [['cost',t.cost],['revenue',t.revenue],['profit',t.profit]];}if(key==='sales')return [];if(key==='stock')return [['value',Math.round(x.quantity*x.cost)],['potential',Math.round(x.quantity*(x.price-x.cost))]];if(key==='creditCards')return [['available',Math.max(0,x.limit-x.debt)]];if(key==='mortgages')return [['balance',x.balance]];if(key==='mortgagePayments')return [['total',x.amount+(x.interest||0)]];return [];}
 const labels={cards:['Себестоимость','Должны','Прибыль'],sales:[],stock:['Стоимость остатка','Потенциальная прибыль'],creditCards:['Доступный лимит'],mortgages:['Остаток долга'],mortgagePayments:['Всего платёж']};
 function computedDisplay(key,x,k,v){return (v===null?'—':rub(v))+(key==='cards'&&k==='profit'&&cardTotals(x).pending?`<small class="card-potential">Потенциальный доход<br>${rub(cardTotals(x).potentialProfit)}</small>`:'');}
 function rowHtml(key,x,isNew=false){return `<tr data-id="${esc(x.id)}" ${isNew?'data-new="true"':''}>${schemas[key].map(([f,,t],i)=>cell(x,f,t,i,key)).join('')}${computed(key,x).map(([k,v])=>`<td class="ledger-computed" data-computed="${k}">${computedDisplay(key,x,k,v)}</td>`).join('')}${key==='cards'?`<td>${cardTotals(x).pending?'Тираж уточняется':cardTotals(x).debt?`<button data-fin="card-payment" data-id="${x.id}">Доплатить остаток — ${rub(cardTotals(x).debt)}</button>`: "Оплачено"}</td>`:key==='mortgages'?`<td><button data-ledger="loan" data-id="${x.id}">Платежи</button></td>`:''}</tr>`;}
 function table(key,parent='',title=''){const source=rowsFor(key,parent).filter(x=>key!=='cards'||ledgerCardYear==='all'||String(x.incomeMonth||x.date||x.sourceYear||'').startsWith(ledgerCardYear)),rows=['cards','sales'].includes(key)?newestFinanceRecords(source):source;return `${title?`<h3>${title}</h3>`:''}<div class="row between"><span class="footnote">${rows.length} записей</span>${key==='familyComponents'?'':`<button data-ledger="add" data-key="${key}" data-parent="${parent}" class="secondary">＋ Строка</button>`}</div><div class="finance-grid-wrap"><table class="finance-grid ledger-grid" data-key="${key}" data-parent="${parent}"><thead><tr>${schemas[key].map(([,l])=>`<th>${l}</th>`).join('')}${(labels[key]||[]).map(l=>`<th>${l}</th>`).join('')}${key==='cards'||key==='mortgages'?'<th>Действие</th>':''}</tr></thead><tbody>${rows.map(x=>rowHtml(key,x)).join('')}</tbody></table></div>`;}
 const pages={cards:'Визитки',sales:'Продажи',stock:'Склад'};
 function view(key){const years=[...new Set([new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Novosibirsk',year:'numeric'}).format(new Date()),...getData().cards.map(x=>String(x.incomeMonth||x.date||x.sourceYear||'').slice(0,4)).filter(Boolean)])].sort().reverse();return `<h3>${pages[key]} · таблица</h3>${key==='cards'?`<label class="fin-filter">Год заказа<select id="ledger-card-year"><option value="all" ${ledgerCardYear==='all'?'selected':''}>Все годы</option>${years.map(y=>`<option ${y===ledgerCardYear?'selected':''}>${y}</option>`).join('')}</select></label>`:''}${status()}${table(key)}`;}
 function moreView(){const d=getData();loanId=d.mortgages.some(x=>x.id===loanId)?loanId:d.mortgages[0]?.id||'';familyId=d.family.some(x=>x.id===familyId)?familyId:d.family[0]?.id||'';const family=d.family.find(x=>x.id===familyId);return `<nav class="fin-view-toggle ledger-section-nav">${[['accounts','Счета'],['mortgages','Ипотеки'],['family','Семейные расчёты']].map(([k,l])=>`<button data-ledger="section" data-section="${k}" class="${moreTab===k?'selected':''}">${l}</button>`).join('')}</nav>${status()}${moreTab==='accounts'?`${table('accounts','','Счета и наличные')}${table('creditCards','','Кредитные карты')}<section class="panel"><div class="fin-line"><span>Осталось передать · Работа</span><b>${workDue()===null?'Нет связи':rub(workDue())}</b></div><div class="fin-line"><span>Корректировка общего долга, ₽</span><input data-extra-credit value="${(d.credit-(d.creditCards||[]).reduce((n,x)=>n+x.debt,0))/100}" data-original="${(d.credit-(d.creditCards||[]).reduce((n,x)=>n+x.debt,0))/100}" aria-label="Корректировка общего долга, ₽" inputmode="decimal"></div><div class="fin-line"><span>Резерв, ₽</span><input data-reserve value="${d.reserved/100}" data-original="${d.reserved/100}" aria-label="Резерв, ₽" inputmode="decimal"></div><div class="fin-line"><span>Свободные собственные средства</span><b data-free>${workDue()===null?'Уточняется':rub(d.accounts.filter(x=>x.owned!==false).reduce((n,x)=>n+x.balance,0)-d.credit-d.reserved-workDue())}</b></div></section>`:moreTab==='mortgages'?`${table('mortgages','','Ипотеки')}<p class="footnote">Остаток долга изменяется на разницу основного долга в платежах. Выберите ипотеку кнопкой «Платежи».</p>${loanId?table('mortgagePayments',loanId,'Платежи · '+esc(d.mortgages.find(x=>x.id===loanId).name)):''}`:family?`<h3>${esc(family.name)}</h3><p class="fin-metric" data-family-balance>${family.balanceUnknown?'Остаток требует уточнения':rub(family.balance)}</p><label class="field">Начальный долг, ₽<input data-family-initial data-parent="${family.id}" value="${family.initial/100}" data-original="${family.initial/100}" inputmode="decimal"></label>${table('familyComponents',familyId,'Итоги категорий')}<p class="footnote">Пустые суммы ЖКХ / комиссии означают отсутствие внешних данных. Итоги других категорий изменяются вместе с операциями. Даты старых операций можно оставить пустыми.</p>${table('familyPayments',familyId,'Операции')}`:'<p>Семейных расчётов пока нет.</p>'}`;}
 function parseRow(table,row){const key=table.dataset.key,old=rowsFor(key,table.dataset.parent).find(x=>x.id===row.dataset.id),x=structuredClone(old||{id:row.dataset.id});for(const [f,,type]of schemas[key]){const e=row.querySelector(`[data-field="${f}"]`);if(!e)continue;let v=e.value.trim();if(old&&v===e.dataset.original)continue;if(type==='owner')v=v==='true';else if(key==='cards'&&f==='actualQuantity'&&!v)v=null;else if(moneyTypes.has(type)||type==='qty')v=number(v,type);else if(type==='date'&&v&&!validDate(v))throw Error('Проверьте дату.');else if(type==='month'&&v&&!/^20\d\d-(0[1-9]|1[0-2])$/.test(v))throw Error('Проверьте месяц.');if(type==='text'&&v.length>500)throw Error('Слишком длинное значение.');x[f]=v;}
 if(['cards','sales','stock','accounts','mortgages'].includes(key)&&!x.name?.trim()||key==='creditCards'&&!x.bank?.trim())throw Error('Укажите название / банк.');
 if(key==='mortgages'){if(!old){x.balance=x.initial;x.payments=[];}else x.balance=old.balance+x.initial-old.initial;}
 if(key==='cards'){if(!old||x.quantity!==old.quantity||x.unitCost!==old.unitCost)delete x.costOverride;if(!old||x.actualQuantity!==old.actualQuantity||x.unitPrice!==old.unitPrice)delete x.revenueOverride;}
 if(key==='sales'){if(x.profitOnly){const profit=x.legacyProfit??(x.received-x.cost);x.revenue=x.received=Math.max(0,profit);x.cost=Math.max(0,profit)-profit;}delete x.legacyProfit;}
 return {key,parent:table.dataset.parent,x,old};}
 function update(){try{root.querySelectorAll('.ledger-grid').forEach(t=>t.querySelectorAll('tbody tr').forEach(r=>{const {key,x}=parseRow(t,r);computed(key,x).forEach(([k,v])=>r.querySelector(`[data-computed="${k}"]`).innerHTML=computedDisplay(key,x,k,v));if(key==='sales'&&!x.profitOnly)r.querySelector('[data-computed="profit"]').textContent=rub(x.received-x.cost);if(key==='cards'){const debt=cardTotals(x).debt;r.lastElementChild.innerHTML=cardTotals(x).pending?'Тираж уточняется':debt?`<button data-fin="card-payment" data-id="${x.id}">Доплатить остаток — ${rub(debt)}</button>`:'Оплачено';}}));const free=root.querySelector('[data-free]');if(free){const accounts=[...root.querySelector('.ledger-grid[data-key="accounts"]').querySelectorAll('tbody tr')].map(r=>parseRow(root.querySelector('.ledger-grid[data-key="accounts"]'),r).x),credits=[...root.querySelector('.ledger-grid[data-key="creditCards"]').querySelectorAll('tbody tr')].map(r=>parseRow(root.querySelector('.ledger-grid[data-key="creditCards"]'),r).x);free.textContent=workDue()===null?'Уточняется':rub(accounts.filter(x=>x.owned!==false).reduce((n,x)=>n+x.balance,0)-credits.reduce((n,x)=>n+x.debt,0)-number(root.querySelector('[data-extra-credit]').value,'signed')-number(root.querySelector('[data-reserve]').value,'money')-workDue());}}catch{/* Validation is displayed on Save; incomplete draft cells remain editable. */}}
 let autoTimer;
 function mark(){dirty=true;clearTimeout(autoTimer);autoTimer=setTimeout(autoSave,650);const s=root.querySelector('.ledger-status');if(s)s.textContent='Есть несохранённые изменения';update();}
 async function commit(){const patches=[];root.querySelectorAll('.ledger-grid').forEach(t=>t.querySelectorAll('tbody tr').forEach(r=>patches.push(parseRow(t,r))));const d=getData(),reserve=root.querySelector('[data-reserve]'),initial=root.querySelector('[data-family-initial]'),newReserve=reserve?number(reserve.value,'money'):d.reserved,newInitial=initial?number(initial.value,'money'):null,extraCredit=root.querySelector('[data-extra-credit]'),creditAdjustment=extraCredit?number(extraCredit.value,'signed'):0;const proposedCredit=patches.filter(p=>p.key==='creditCards').reduce((n,p)=>n+p.x.debt,0)+creditAdjustment;if(extraCredit&&proposedCredit<0)throw Error('Общий долг не может быть отрицательным.');
 const familyExternalChanges=new Map();for(const {key,parent,x,old}of patches)if(key==='familyPayments'){for(const [cat,n]of [[old?.category,-(old?.amount||0)],[x.category,x.amount]])if(['ЖКХ','Комиссия ЖКХ'].includes(cat)){const id=parent+'|'+cat;familyExternalChanges.set(id,(familyExternalChanges.get(id)||0)+n);}}
 const loanChanges=new Map();for(const p of patches)if(p.key==='mortgagePayments')loanChanges.set(p.parent,(loanChanges.get(p.parent)||0)+(p.old?.amount||0)-p.x.amount);for(const [id,delta]of loanChanges)if((patches.find(p=>p.key==='mortgages'&&p.x.id===id)?.x.balance??d.mortgages.find(x=>x.id===id).balance)+delta<0)throw Error('Платежи превышают остаток ипотеки.');
 for(const {key,x,old,parent}of patches){if(key==='cards'){x.payments=old?.payments||[];const delta=x.received-(old?.received||0);if(delta)x.payments.push({id:uid(),amount:delta,date:today(),note:'Корректировка из таблицы визиток'});}let target=key==='creditCards'?d.creditCards||(d.creditCards=[]):key==='mortgagePayments'?d.mortgages.find(z=>z.id===parent).payments:key==='familyPayments'?d.family.find(z=>z.id===parent).payments:key==='familyComponents'?d.family.find(z=>z.id===parent).components:d[key];const at=key==='creditCards'&&/^credit-\d+$/.test(x.id)?Number(x.id.slice(7)):target.findIndex(z=>z.id===x.id);if(at>=0)target[at]=x;else target.push(x);}
 for(const [id,delta]of loanChanges)d.mortgages.find(x=>x.id===id).balance+=delta;
 if(root.querySelector('.ledger-grid[data-key="creditCards"]'))d.credit=d.creditCards.reduce((n,x)=>n+x.debt,0)+creditAdjustment;d.reserved=newReserve;
 if(initial){const family=d.family.find(x=>x.id===initial.dataset.parent);family.initial=newInitial;for(const c of family.components)if(['ЖКХ','Комиссия ЖКХ'].includes(c.name)&&c.amount!==null)c.amount+=familyExternalChanges.get(family.id+'|'+c.name)||0;for(const c of family.components)if(!['ЖКХ','Комиссия ЖКХ'].includes(c.name))c.amount=family.payments.filter(p=>p.category===c.name).reduce((n,p)=>n+p.amount,0);family.balanceUnknown=family.components.some(c=>c.amount===null);family.balance=family.balanceUnknown?0:family.initial-family.components.reduce((n,c)=>n+c.amount,0);}
 await save();dirty=false;
 }
 async function autoSave(){if(!dirty)return;if(busy){autoTimer=setTimeout(autoSave,250);return;}busy=true;const snapshots=[...root.querySelectorAll('.ledger-grid [data-original],[data-reserve],[data-family-initial],[data-extra-credit]')].map(e=>[e,e.value]),status=root.querySelector('.ledger-status');if(status)status.textContent='Сохраняется…';try{await commit(); snapshots.forEach(([e,v])=>{e.dataset.original=v;e.closest('[data-new]')?.removeAttribute('data-new');});dirty=snapshots.some(([e,v])=>e.value!==v);root.querySelector('.ledger-error').textContent='';if(status)status.textContent=dirty?'Сохраняется…':'Все изменения сохранены';if(dirty)autoTimer=setTimeout(autoSave,250);}catch(err){dirty=true;root.querySelector('.ledger-error').textContent=err.message;if(status)status.textContent='Не сохранено';}finally{busy=false;}}
 root.addEventListener('input',e=>{if(e.target.closest('.ledger-grid')||e.target.matches('[data-reserve],[data-family-initial],[data-extra-credit]'))mark();});root.addEventListener('change',e=>{if(e.target.id==='ledger-card-year'){if(dirty){e.target.value=ledgerCardYear;alert('Дождитесь автосохранения или исправьте поле с ошибкой.');return;}ledgerCardYear=e.target.value;render();return;}if(e.target.closest('.ledger-grid')&&e.target.value!==e.target.dataset.original)mark();});
 root.addEventListener('keydown',e=>{if(!e.target.closest('.ledger-grid'))return;if(e.key==='Escape'){e.target.value=e.target.dataset.original;mark();}if(e.key==='Enter'){e.preventDefault();e.target.blur();}});
 root.addEventListener('paste',e=>{const cell=e.target.closest('.ledger-grid [data-cell]');if(!cell)return;const text=e.clipboardData.getData('text/plain');if(!/[\t\r\n]/.test(text))return;e.preventDefault();const rows=[...cell.closest('tbody').querySelectorAll('tr')],start=rows.indexOf(cell.closest('tr')),col=Number(cell.dataset.cell),matrix=text.trimEnd().split(/\r?\n/).map(x=>x.split('\t')),staged=[];try{for(let i=0;i<matrix.length;i++)for(let j=0;j<matrix[i].length;j++){const target=rows[start+i]?.querySelector(`[data-cell="${col+j}"]`);if(!target)throw Error('Недостаточно полей / строк для диапазона. Добавьте строки; не включайте вычисляемые итоги.');let v=matrix[i][j].trim();if(target.type==='date'&&/^\d{2}\.\d{2}\.\d{4}$/.test(v))v=v.split('.').reverse().join('-');if(target.matches('select')&&![...target.options].some(o=>o.value===v))throw Error('Значение не соответствует вариантам списка.');staged.push([target,v]);}staged.forEach(([target,v])=>target.value=v);mark();root.querySelector('.ledger-error').textContent='';}catch(err){root.querySelector('.ledger-error').textContent=err.message;}});
 root.addEventListener('click',async e=>{const b=e.target.closest('[data-ledger]');if(!b||busy)return;const action=b.dataset.ledger;if(action==='save'){busy=true;b.disabled=true;try{await commit();}catch(err){root.querySelector('.ledger-error').textContent=err.message;root.querySelector('.ledger-status').textContent='Не сохранено';}finally{busy=false;b.disabled=false;}return;}if(action==='cancel'){root.querySelectorAll('.ledger-grid [data-original],[data-reserve],[data-family-initial],[data-extra-credit]').forEach(x=>x.value=x.dataset.original);root.querySelectorAll('.ledger-grid [data-new]').forEach(x=>x.remove());dirty=false;update();root.querySelector('.ledger-status').textContent='Изменения отменены';root.querySelector('.ledger-error').textContent='';return;}if(action==='section'||action==='loan'){if(dirty){alert('Дождитесь автосохранения или исправьте поле с ошибкой.');return;}if(action==='section')moreTab=b.dataset.section;else loanId=b.dataset.id;render();return;}if(action==='add'){const key=b.dataset.key,parent=b.dataset.parent,t=root.querySelector(`.ledger-grid[data-key="${key}"][data-parent="${parent}"]`),x={id:uid(),name:'',date:today(),incomeMonth:today().slice(0,7),quantity:key==='stock'?0:1,actualQuantity:null,unitCost:0,unitPrice:0,received:0,revenue:0,cost:0,price:0,balance:0,owned:true,bank:'',debt:0,limit:0,initial:0,amount:0,interest:0,note:'',source:'',category:'Прочее',payments:[]};t.querySelector('tbody').insertAdjacentHTML('afterbegin',rowHtml(key,x,true));mark();t.closest('.finance-grid-wrap').scrollTop=0;t.querySelector('tbody tr:first-child input')?.focus();}});
 return {view,moreView,hasDirty:()=>dirty};
}
